// application.conf:
// db-dispatcher { type = Dispatcher
//   thread-pool-executor { fixed-pool-size = 8 } }

val db = context.spawn(DbGuardian(), "db",
  DispatcherSelector.fromConfig("db-dispatcher"))

db ! Query(sql, replyTo)     // blocking DB work confined to 8 threads

val dbSlots = Semaphore[IO](8).unsafeRunSync()

def query(sql: String): IO[Rows] =
  dbSlots.permit.use { _ =>
    db.query[IO](sql)          // permit released on cancel, error or defect
  }

